import { CONTACT_EMAIL } from "./legal";

const SITE_URL = "https://www.chaintvl.com";
const SITE_NAME = "ChainTVL";
const ORGANIZATION_ID = `${SITE_URL}/#organization`;
const WEBSITE_ID = `${SITE_URL}/#website`;
// Square (512x512) generated by app/icon.tsx; Google wants a square logo, not the 1200x630 social card.
const LOGO_URL = `${SITE_URL}/icon`;

/** Organization + WebSite as one linked graph (WebSite.publisher points at the Organization). */
export function siteGraphSchema() {
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": ORGANIZATION_ID,
        name: SITE_NAME,
        url: SITE_URL,
        logo: { "@type": "ImageObject", url: LOGO_URL, width: 512, height: 512 },
        contactPoint: {
          "@type": "ContactPoint",
          contactType: "customer support",
          email: CONTACT_EMAIL,
        },
      },
      {
        "@type": "WebSite",
        "@id": WEBSITE_ID,
        name: SITE_NAME,
        url: SITE_URL,
        description:
          "Track total value locked (TVL) across every major blockchain and see where crypto capital is moving between chains.",
        inLanguage: "en-US",
        publisher: { "@id": ORGANIZATION_ID },
      },
    ],
  };
}

export function webPageSchema(opts: { path: string; name: string; description: string; dateModified?: string }) {
  const url = `${SITE_URL}${opts.path}`;
  return {
    "@context": "https://schema.org",
    "@type": "WebPage",
    "@id": `${url}#webpage`,
    url,
    name: opts.name,
    description: opts.description,
    inLanguage: "en-US",
    isPartOf: { "@id": WEBSITE_ID },
    ...(opts.dateModified ? { dateModified: opts.dateModified } : {}),
  };
}

export function breadcrumbSchema(items: { name: string; url: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: item.name,
      item: item.url,
    })),
  };
}

export function faqSchema(items: { question: string; answer: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: {
        "@type": "Answer",
        text: item.answer,
      },
    })),
  };
}

function isoDate(unixSeconds: number): string {
  return new Date(unixSeconds * 1000).toISOString().slice(0, 10);
}

type DatedSeries = Array<{ date: number }>;

/**
 * Dataset for one chain's published series. Coverage and dateModified come
 * from the data itself (each chain's history starts on a different day), and
 * the stablecoin variable is listed only when that series is actually shown.
 */
export function chainDatasetSchema(opts: {
  chainName: string;
  url: string;
  description: string;
  tvlHistory: DatedSeries;
  stablecoinHistory: DatedSeries;
}) {
  const series = [opts.tvlHistory, opts.stablecoinHistory].filter((s) => s.length > 0);
  const bounds = series.flatMap((s) => [s[0].date, s[s.length - 1].date]);
  const start = bounds.length ? Math.min(...bounds) : null;
  const end = bounds.length ? Math.max(...bounds) : null;
  const hasStablecoin = opts.stablecoinHistory.length > 0;

  const variableMeasured = [
    { "@type": "PropertyValue", name: "Total value locked", unitText: "USD" },
    ...(hasStablecoin ? [{ "@type": "PropertyValue", name: "Stablecoin circulating supply", unitText: "USD" }] : []),
  ];

  return {
    "@context": "https://schema.org",
    "@type": "Dataset",
    "@id": `${opts.url}#dataset`,
    name: hasStablecoin
      ? `${opts.chainName} TVL and stablecoin supply history`
      : `${opts.chainName} TVL history`,
    description: opts.description,
    url: opts.url,
    inLanguage: "en-US",
    isAccessibleForFree: true,
    variableMeasured,
    ...(start !== null && end !== null
      ? { temporalCoverage: `${isoDate(start)}/${isoDate(end)}`, dateModified: isoDate(end) }
      : {}),
    publisher: { "@id": ORGANIZATION_ID },
    creator: {
      "@type": "Organization",
      name: "DefiLlama",
      url: "https://defillama.com",
    },
    isBasedOn: ["https://api.llama.fi", "https://stablecoins.llama.fi"],
  };
}
